func cleanMark(m *Mark) *Mark {
	out := &Mark{Type: m.Type}
	switch m.Type {
	case "highlight":
		if c, ok := allowedColor("h", highlightColors, m.Attrs["color"]); ok {
			out.Attrs = map[string]any{"color": c}
		}
	case "textStyle":
		c, ok := allowedColor("c", textColors, m.Attrs["color"])
		if !ok {
			return nil
		}
		out.Attrs = map[string]any{"color": c}
	case "link":
		href, _ := m.Attrs["href"].(string)
		out.Attrs = map[string]any{"href": SafeHref(href)}
	}
	return out
}

// SafeHref keeps http(s), mailto, tel and k3 links and paths of the app; anything else gives "".
func SafeHref(h string) string {
	h = strings.TrimSpace(h)
	if h == "" || len(h) > 2000 {
		return ""
	}
	if strings.HasPrefix(h, "/") && !strings.HasPrefix(h, "//") && !strings.ContainsAny(h, "\\\n\r\t") {
		return h
	}
	u, err := url.Parse(h)
	if err != nil {
		return ""
	}
	switch strings.ToLower(u.Scheme) {
	case "http", "https":
		if u.Host == "" {
			return ""
		}
		return u.String()
	case "mailto", "tel":
		return h
	case "k3":
		if ValidRef(h) {
			return h
		}
	}
	return ""
}

// ValidRef: a k3:// reference to one record (k3://app/type/id).
func ValidRef(ref string) bool {
	if ref == "" || len(ref) > 300 {
		return false
	}
	r, err := k3.ParseReference(ref)
	return err == nil && r.ID != "" && len(r.Query) == 0
}

func imageIDOf(a map[string]any) string {
	if id, ok := a["imageId"].(string); ok && imageIDRe.MatchString(id) {
		return id
	}
	if src, ok := a["src"].(string); ok {
		if m := imageSrc.FindStringSubmatch(src); m != nil {
			return m[1]
		}
	}
	return ""
}

func alignAttr(in, out map[string]any) {
	if a, ok := in["textAlign"].(string); ok && (a == "center" || a == "right" || a == "justify") {
		out["textAlign"] = a
	}
}

